#include "Database.hpp"

#include <cstring>
#include "builtin_bin.h"   // generated by bin2o from Data/builtin.bin (made by tools/build_db.py)

namespace McM3
{
    // Index entry layout written by tools/build_db.py
    struct Entry
    {
        u64 titleId;
        u32 offset;
        u32 packedSize;
        u32 rawSize;
        u32 flags;
    };

    static const u8 *Db(void) { return builtin_bin; }

    static bool Valid(void)
    {
        return builtin_bin_size >= 12 && memcmp(Db(), "MCM3DB01", 8) == 0;
    }

    u32 BuiltinGameCount(void)
    {
        if (!Valid())
            return 0;
        u32 count;
        memcpy(&count, Db() + 8, 4);
        return count;
    }

    static bool ReadEntry(u32 i, Entry &e)
    {
        const u32 pos = 12 + i * 24;
        if (pos + 24 > builtin_bin_size)
            return false;
        memcpy(&e.titleId,    Db() + pos,      8);
        memcpy(&e.offset,     Db() + pos + 8,  4);
        memcpy(&e.packedSize, Db() + pos + 12, 4);
        memcpy(&e.rawSize,    Db() + pos + 16, 4);
        memcpy(&e.flags,      Db() + pos + 20, 4);
        return (u64)e.offset + e.packedSize <= builtin_bin_size;
    }

    // Decoder for tools/lz.py. Returns false on corrupt data.
    static bool Unpack(const u8 *in, u32 inSize, std::string &out, u32 rawSize)
    {
        out.clear();
        out.reserve(rawSize);
        u32 i = 0;

        auto readLen = [&](u32 &len) -> bool
        {
            if (len != 15)
                return true;
            while (true)
            {
                if (i >= inSize) return false;
                u8 b = in[i++];
                len += b;
                if (b != 255) return true;
            }
        };

        while (i < inSize)
        {
            u8 token = in[i++];
            u32 lit = token >> 4;
            if (!readLen(lit) || i + lit > inSize)
                return false;
            out.append((const char *)in + i, lit);
            i += lit;
            if (i >= inSize)
                break;

            if (i + 2 > inSize)
                return false;
            u32 off = in[i] | (in[i + 1] << 8);
            i += 2;
            u32 len = token & 15;
            if (!readLen(len))
                return false;
            len += 4;
            if (off == 0 || off > out.size() || out.size() + len > rawSize)
                return false;
            size_t start = out.size() - off;
            for (u32 k = 0; k < len; k++)
                out.push_back(out[start + k]);
        }
        return out.size() == rawSize;
    }

    bool FindBuiltin(u64 titleId, std::string &name, std::string &text, u32 &flags)
    {
        const u32 count = BuiltinGameCount();

        // Index is sorted by title ID
        u32 lo = 0, hi = count;
        while (lo < hi)
        {
            u32 mid = (lo + hi) / 2;
            Entry e;
            if (!ReadEntry(mid, e))
                return false;
            if (e.titleId == titleId)
            {
                std::string raw;
                if (!Unpack(Db() + e.offset, e.packedSize, raw, e.rawSize))
                    return false;
                size_t nl = raw.find('\n');
                name = raw.substr(0, nl);
                text = (nl == std::string::npos) ? std::string() : raw.substr(nl + 1);
                flags = e.flags;
                return true;
            }
            if (e.titleId < titleId) lo = mid + 1;
            else hi = mid;
        }
        return false;
    }
}
